-- Left-to-right direction: (r ∪ s) ∩ (r ∪ t) ⊆ r ∪ s ∩ t
intro x
have : x ∈ r ∪ s ∧ x ∈ r ∪ t := by
  -- x ∈ r ∪ s
  cases x ∈ r with | inr x
  { exact ⟨x, by simp⟩ }
  | inl x
  { exact ⟨x, by simp⟩ }
  -- x ∈ r ∪ t
  cases x ∈ r with | inr x
  { exact ⟨x, by simp⟩ }
  | inl x
  { exact ⟨x, by simp⟩ }
have : x ∈ r ∪ s ∧ x ∈ r ∪ t := by
  -- x ∈ r ∪ s
  cases x ∈ r with | inr x
  { exact ⟨x, by simp⟩ }
  | inl x
  { exact ⟨x, by simp⟩ }
  -- x ∈ r ∪ t
  cases x ∈ t with | inr x
  { exact ⟨x, by simp⟩ }
  | inl x
  { exact ⟨x, by simp⟩ }
-- Now show x ∈ r ∪ s ∩ t
have : x ∈ r ∪ s := by
  cases x ∈ r with | inr x
  { exact ⟨x, by simp⟩ }
  | inl x
  { exact ⟨x, by simp⟩ }
have : x ∈ r ∪ t := by
  cases x ∈ t with | inr x
  { exact ⟨x, by simp⟩ }
  | inl x
  { exact ⟨x, by simp⟩ }
exact ⟨x, by simp⟩

-- Right-to-left direction: r ∪ s ∩ t ⊆ (r ∪ s) ∩ (r ∪ t)
intro x
have : x ∈ r ∪ s ∧ x ∈ t := by
  -- x ∈ r ∪ s
  cases x ∈ r with | inr x
  { exact ⟨x, by simp⟩ }
  | inl x
  { exact ⟨x, by simp⟩ }
  -- x ∈ t
  cases x ∈ t with | inr x
  { exact ⟨x, by simp⟩ }
  | inl x
  { exact ⟨x, by simp⟩ }
have : x ∈ r ∪ s ∧ x ∈ r ∪ t := by
  -- x ∈ r ∪ s
  cases x ∈ r with | inr x
  { exact ⟨x, by simp⟩ }
  | inl x
  { exact ⟨x, by simp⟩ }
  -- x ∈ r ∪ t
  cases x ∈ r with | inr x
  { exact ⟨x, by simp⟩ }
  | inl x
  { exact ⟨x, by simp⟩ }
exact ⟨x, by simp⟩

-- Using Finset properties
rw [Finset.union_inter_left, Finset.union_inter_right]
exact by simp [Finset.union_inter_left, Finset.union_inter_right]
